-- 1. Create Tables
-- Update existing identity columns to GENERATED BY DEFAULT
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND is_identity = 'YES'
          AND identity_generation = 'ALWAYS'
    LOOP
        EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I SET GENERATED BY DEFAULT', r.table_name, r.column_name);
    END LOOP;
END $$;

CREATE TABLE IF NOT EXISTS public.admin_whitelist (
    email text NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    role text DEFAULT 'content_manager'::text
);

CREATE TABLE IF NOT EXISTS public.blog_posts (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title text,
    excerpt text,
    content text,
    author text,
    image_url text,
    category text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.donation_funds (
    id text NOT NULL PRIMARY KEY,
    name text NOT NULL,
    is_active boolean DEFAULT true,
    display_order integer GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE IF NOT EXISTS public.donations (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    donor_name text,
    donor_email text,
    amount numeric,
    fund_id text REFERENCES public.donation_funds(id),
    status text,
    payment_id text,
    frequency text,
    pan_number text,
    is_verified boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.gallery_albums (
    id text NOT NULL PRIMARY KEY,
    title text,
    cover_url text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.gallery_images (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    album_id text REFERENCES public.gallery_albums(id) ON DELETE CASCADE,
    image_url text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.impact_stats (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    label text,
    value text,
    description text,
    display_order integer GENERATED BY DEFAULT AS IDENTITY,
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.impact_stories (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title text,
    description text,
    author text,
    location text,
    image_url text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.mission_groups (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title text,
    description text,
    color text,
    icon text,
    display_order integer GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE IF NOT EXISTS public.mission_causes (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id integer REFERENCES public.mission_groups(id) ON DELETE CASCADE,
    title text,
    description text,
    icon text,
    display_order integer GENERATED BY DEFAULT AS IDENTITY,
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.newsletter_subscribers (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email text UNIQUE,
    subscribed_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.partnership_inquiries (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    contact_name text,
    organization text,
    email text,
    phone text,
    inquiry_type text,
    message text,
    status text DEFAULT 'new'::text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.system_settings (
    key text NOT NULL PRIMARY KEY,
    value text,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.team_members (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name text,
    role text,
    bio text,
    image_url text,
    display_order integer GENERATED BY DEFAULT AS IDENTITY,
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.testimonials (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name text,
    role text,
    content text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    approval_status text DEFAULT 'published'::text,
    author_email text,
    reviewer_comments text
);

CREATE TABLE IF NOT EXISTS public.volunteer_applications (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    first_name text,
    last_name text,
    email text,
    phone text,
    interest text,
    status text DEFAULT 'pending'::text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
    amount_paid numeric,
    payment_id text,
    application_type text DEFAULT 'volunteer'::text
);

-- 2. Insert Data
-- Add approval workflow columns to existing tables
DO $$
BEGIN
  -- Content Approval Workflow Columns
  if not exists (select 1 from information_schema.columns where table_name = 'blog_posts' and column_name = 'approval_status') then
    alter table public.blog_posts add column approval_status text default 'published';
    alter table public.blog_posts add column author_email text;
    alter table public.blog_posts add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'gallery_albums' and column_name = 'approval_status') then
    alter table public.gallery_albums add column approval_status text default 'published';
    alter table public.gallery_albums add column author_email text;
    alter table public.gallery_albums add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'impact_stats' and column_name = 'approval_status') then
    alter table public.impact_stats add column approval_status text default 'published';
    alter table public.impact_stats add column author_email text;
    alter table public.impact_stats add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'impact_stories' and column_name = 'approval_status') then
    alter table public.impact_stories add column approval_status text default 'published';
    alter table public.impact_stories add column author_email text;
    alter table public.impact_stories add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'mission_causes' and column_name = 'approval_status') then
    alter table public.mission_causes add column approval_status text default 'published';
    alter table public.mission_causes add column author_email text;
    alter table public.mission_causes add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'team_members' and column_name = 'approval_status') then
    alter table public.team_members add column approval_status text default 'published';
    alter table public.team_members add column author_email text;
    alter table public.team_members add column reviewer_comments text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'testimonials' and column_name = 'approval_status') then
    alter table public.testimonials add column approval_status text default 'published';
    alter table public.testimonials add column author_email text;
    alter table public.testimonials add column reviewer_comments text;
  end if;
END $$;

