-- 3. Create Admin Function
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
begin
  return (auth.role() = 'authenticated' AND exists (
    select 1 from public.admin_whitelist
    where lower(email) = lower(auth.jwt() ->> 'email')
  ));
end;
$$;

