-- 5. Create RLS Policies
-- 1. Create a helper function to get the user's specific role
CREATE OR REPLACE FUNCTION public.get_admin_role()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  user_role text;
BEGIN
  SELECT role INTO user_role FROM public.admin_whitelist WHERE lower(email) = lower(auth.jwt() ->> 'email');
  RETURN user_role;
END;
$$;

