-- Content Creator Access (Own content only, no direct publishing)
-- Blog Posts
DROP POLICY IF EXISTS "Creators read own blog" ON public.blog_posts;
CREATE POLICY "Creators read own blog" ON public.blog_posts FOR SELECT USING (public.get_admin_role() = 'content_creator' AND author_email = auth.jwt() ->> 'email');
DROP POLICY IF EXISTS "Creators insert own blog" ON public.blog_posts;
CREATE POLICY "Creators insert own blog" ON public.blog_posts FOR INSERT WITH CHECK (public.get_admin_role() = 'content_creator' AND author_email = auth.jwt() ->> 'email' AND approval_status IN ('draft', 'pending'));
DROP POLICY IF EXISTS "Creators update own blog" ON public.blog_posts;
CREATE POLICY "Creators update own blog" ON public.blog_posts FOR UPDATE USING (public.get_admin_role() = 'content_creator' AND author_email = auth.jwt() ->> 'email') WITH CHECK (approval_status IN ('draft', 'pending'));
DROP POLICY IF EXISTS "Creators delete own blog" ON public.blog_posts;
CREATE POLICY "Creators delete own blog" ON public.blog_posts FOR DELETE USING (public.get_admin_role() = 'content_creator' AND author_email = auth.jwt() ->> 'email');

