CREATE POLICY "Admin manage mission groups" ON public.mission_groups USING (public.is_admin());
DROP POLICY IF EXISTS "Admin manage partners" ON public.partnership_inquiries;
CREATE POLICY "Admin manage partners" ON public.partnership_inquiries USING (public.is_admin());
DROP POLICY IF EXISTS "Admin manage settings" ON public.system_settings;
CREATE POLICY "Admin manage settings" ON public.system_settings USING (public.is_admin());
DROP POLICY IF EXISTS "Admin manage volunteers" ON public.volunteer_applications;
CREATE POLICY "Admin manage volunteers" ON public.volunteer_applications USING (public.is_admin());
DROP POLICY IF EXISTS "Admin manage whitelist" ON public.admin_whitelist;
CREATE POLICY "Admin manage whitelist" ON public.admin_whitelist USING (public.is_admin());
DROP POLICY IF EXISTS "Admin read donations" ON public.donations;
CREATE POLICY "Admin read donations" ON public.donations FOR SELECT USING (public.is_admin());
DROP POLICY IF EXISTS "Admin read newsletter" ON public.newsletter_subscribers;
CREATE POLICY "Admin read newsletter" ON public.newsletter_subscribers FOR SELECT USING (public.is_admin());

-- 4. Storage Bucket Setup
insert into storage.buckets (id, name, public) values ('images', 'images', true) on conflict do nothing;
DROP POLICY IF EXISTS "Public Access" ON storage.objects;
create policy "Public Access" on storage.objects for select using ( bucket_id = 'images' );
DROP POLICY IF EXISTS "Admin Upload Access" ON storage.objects;
create policy "Admin Upload Access" on storage.objects for insert with check ( bucket_id = 'images' and public.is_admin() );
DROP POLICY IF EXISTS "Admin Update Access" ON storage.objects;
create policy "Admin Update Access" on storage.objects for update using ( bucket_id = 'images' and public.is_admin() );
DROP POLICY IF EXISTS "Admin Delete Access" ON storage.objects;
create policy "Admin Delete Access" on storage.objects for delete using ( bucket_id = 'images' and public.is_admin() );
